mapper.sql:
WITH objRec AS( SELECT PROD_ID, MDATE, BALANCE_AMT, PRD_QTY FROM( SELECT PROD_ID, MDATE, BALANCE_AMT, PRD_QTY, ROW_NUMBER() over( partition by PROD_ID ORDER BY MDATE DESC ) AS durMDateNo FROM( SELECT A.PROD_ID, B.MDATE, B.BALANCE_AMT, B.PRD_QTY, ROW_NUMBER() over( partition by A.PROD_ID , B.MDATE ORDER BY B.UPDATE_TIME DESC) AS durStatusNo FROM CHB_PRD_BASEINFO A INNER JOIN CHB_PRD_DEAL_SUB B ON A.PROD_ID = B.PROD_ID WHERE A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
#{operateMode,jdbcType=VARCHAR}
AND A.FPROD_ID is null AND STR_TO_DATE(DATE_FORMAT(B.MDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) as t1 WHERE durStatusNo = 1 ) as t2 WHERE durMDateNo = 1 OR durMDateNo = 2 )

mapper.select:
SELECT COUNT(DISTINCT(PROD_ID)) FROM (SELECT PROD_ID, MDATE, BALANCE_AMT, PRD_QTY FROM( SELECT PROD_ID, MDATE, BALANCE_AMT, PRD_QTY, ROW_NUMBER() over( partition by PROD_ID ORDER BY MDATE DESC ) AS durMDateNo FROM( SELECT A.PROD_ID, B.MDATE, B.BALANCE_AMT, B.PRD_QTY, ROW_NUMBER() over( partition by A.PROD_ID , B.MDATE ORDER BY B.UPDATE_TIME DESC) AS durStatusNo FROM CHB_PRD_BASEINFO A INNER JOIN CHB_PRD_DEAL_SUB B ON A.PROD_ID = B.PROD_ID WHERE A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
#{operateMode,jdbcType=VARCHAR}
AND A.FPROD_ID is null AND STR_TO_DATE(DATE_FORMAT(B.MDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) as t1 WHERE durStatusNo = 1 ) as t2 WHERE durMDateNo = 1 OR durMDateNo = 2) ZZ

SELECT gg.PROD_ID as prodId, STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') as holdDate, gg.MDATE as busiMDate, IFNULL(gg.BALANCE_AMT,0) as prdBalanceAmt, IFNULL(gg.PRD_QTY,0) as prdTotalQty, IFNULL(gg.TOTAL_AMT,0) as prdRaiseTotalAmt, IFNULL(gg.RAISE_QTY,0) as prdRaiseTotalQty, IFNULL(SUM(gg.CNY_AMT),0) as investBalanceAmt, IFNULL(SUM(gg.QTY),0) as investTotalQty, gg.REG_CODE as prdRegistCode FROM ( SELECT @rownum :=@rownum +1 rownum, tmp1.PROD_ID, tmp1.MDATE, tmp1.BALANCE_AMT, tmp1.PRD_QTY, tmp1.TOTAL_AMT, tmp1.RAISE_QTY, CASE WHEN C.STATUS = '03' THEN 0 ELSE C.CNY_AMT END CNY_AMT, CASE WHEN C.STATUS = '03' THEN 0 ELSE C.QTY END QTY, D.REG_CODE, IF ((@PROD_ID = tmp1.PROD_ID AND @MDATE = tmp1.MDATE), @rank :=@rank + 1, @rank :=1 ) AS hodeStsNo, @PROD_ID := tmp1.PROD_ID, @MDATE := tmp1.MDATE FROM (SELECT * FROM ( SELECT bb.PROD_ID, bb.MDATE, bb.BALANCE_AMT, bb.PRD_QTY, bb.TOTAL_AMT, bb.RAISE_QTY FROM( SELECT @rownum :=@rownum +1 rownum, A.PROD_ID, A.MDATE, A.BALANCE_AMT, A.PRD_QTY, B.TOTAL_AMT, B.RAISE_QTY, IF ((@PROD_ID = A.PROD_ID AND @MDATE = A.MDATE), @rank :=@rank + 1, @rank :=1 ) AS raiseStatusNo, @PROD_ID := A.PROD_ID, @MDATE := A.MDATE FROM (SELECT * FROM (SELECT PROD_ID, MDATE, BALANCE_AMT, PRD_QTY FROM( SELECT PROD_ID, MDATE, BALANCE_AMT, PRD_QTY, ROW_NUMBER() over( partition by PROD_ID ORDER BY MDATE DESC ) AS durMDateNo FROM( SELECT A.PROD_ID, B.MDATE, B.BALANCE_AMT, B.PRD_QTY, ROW_NUMBER() over( partition by A.PROD_ID , B.MDATE ORDER BY B.UPDATE_TIME DESC) AS durStatusNo FROM CHB_PRD_BASEINFO A INNER JOIN CHB_PRD_DEAL_SUB B ON A.PROD_ID = B.PROD_ID WHERE A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
#{operateMode,jdbcType=VARCHAR}
AND A.FPROD_ID is null AND STR_TO_DATE(DATE_FORMAT(B.MDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) as t1 WHERE durStatusNo = 1 ) as t2 WHERE durMDateNo = 1 OR durMDateNo = 2) FF ORDER BY PROD_ID,MDATE ) A INNER JOIN CHB_PRD_RAISETOT_SUB B ON A.PROD_ID = B.PROD_ID left join (SELECT @rownum :=0, @PROD_ID := NULL,@MDATE := NULL, @rank := 0) tmp on 1=1 ) bb WHERE raiseStatusNo = 1 ) ff ORDER BY MDATE ) tmp1 LEFT JOIN CHB_PRDRESIST_CODE D ON tmp1.PROD_ID = D.PRODID LEFT JOIN CHB_INVESTHOLD_INFO_SUB C ON tmp1.PROD_ID = C.PRODID left join (SELECT @rownum :=0, @PROD_ID := NULL, @MDATE := NULL,@rank := 0) tmp on 1=1 WHERE STR_TO_DATE(DATE_FORMAT(C.HOLD_DATE, '%Y-%m-%d'), '%Y-%m-%d') = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) gg WHERE gg.hodeStsNo = 1 GROUP BY gg.PROD_ID, gg.REG_CODE, gg.MDATE, gg.BALANCE_AMT, gg.PRD_QTY, gg.TOTAL_AMT, gg.RAISE_QTY
